      if (ix < 0x3fefffff) return hy < 0 ? s*huge*huge : s*tiny*tiny;
      if (ix > 0x3ff00000) return hy > 0 ? s*huge*huge : s*tiny*tiny;
      t = ax-1.0;
      w = (t*t)*(0.5-t*(0.3333333333333333333333-t*0.25));
      u = ivln2_h*t;
      v = t*ivln2_l-w*ivln2;
      t1 = fl_with_lo(u+v, 0);
      t2 = v-(t1-u);
