      s_h = fl_with_lo(ss, 0);
      t_h = fl_make((fl_u32)(((ix>>1)|0x20000000)+0x00080000+(k<<18)), 0);
      t_l = ax-(t_h-bp[k]);
      s_l = v*((u-s_h*t_h)-s_h*t_l);
      s2 = ss*ss;
      r = s2*s2*(L1+s2*(L2+s2*(L3+s2*(L4+s2*(L5+s2*L6)))));
      r += s_l*(s_h+ss);
      ss2 = s_h*s_h;
      t_h = fl_with_lo(3.0+ss2+r, 0);
      t_l = r-((t_h-3.0)-ss2);
      u = s_h*t_h;
      v = s_l*t_h+t_l*ss;
      p_h = fl_with_lo(u+v, 0);
