   u = t*lg2_h;
   v = (p_l-(t-p_h))*lg2+t*lg2_l;
   z = u+v;
   w = v-(z-u);
   t = z*z;
   t1 = z-t*(P1+t*(P2+t*(P3+t*(P4+t*P5))));
   r = (z*t1)/(t1-2.0)-(w+z*w);
   z = 1.0-(r-z);
   j = (fl_i32)fl_hi(z);
   j += (fl_i32)((fl_u32)n<<20);
   if ((j>>20) <= 0) z = fl_scalbn(z, n);
   else z = fl_with_hi(z, (fl_u32)j);
