#define oe_PE_MAX_NB_SUBFR             4

#define oe_PE_SUBFR_LENGTH_MS          5

#define oe_PE_LTP_MEM_LENGTH_MS        ( 4 * oe_PE_SUBFR_LENGTH_MS )

#define oe_PE_MAX_FRAME_LENGTH_MS      ( oe_PE_LTP_MEM_LENGTH_MS + oe_PE_MAX_NB_SUBFR * oe_PE_SUBFR_LENGTH_MS )




#define oe_PE_MAX_LAG_MS               18

#define oe_PE_MIN_LAG_MS               2

#define oe_PE_MAX_LAG                  ( oe_PE_MAX_LAG_MS * oe_PE_MAX_FS_KHZ )


#define oe_PE_D_SRCH_LENGTH            24

#define oe_PE_NB_STAGE3_LAGS           5

#define oe_PE_NB_CBKS_STAGE2           3

#define oe_PE_NB_CBKS_STAGE2_EXT       11

#define oe_PE_NB_CBKS_STAGE3_MAX       34

#define oe_PE_NB_CBKS_STAGE3_MID       24

#define oe_PE_NB_CBKS_STAGE3_MIN       16

#define oe_PE_NB_CBKS_STAGE3_10MS      12

#define oe_PE_NB_CBKS_STAGE2_10MS      3

#define oe_PE_SHORTLAG_BIAS            0.2f

#define oe_PE_PREVLAG_BIAS             0.2f

#define oe_PE_FLATCONTOUR_BIAS         0.05f

