/* silk/stereo_encode_pred.c */

static void oe_silk_stereo_encode_pred(
    oe_ec_enc                      *psRangeEnc,
    oe_opus_int8                   ix[ 2 ][ 3 ]
)
{
    oe_opus_int   n;

    n = 5 * ix[ 0 ][ 2 ] + ix[ 1 ][ 2 ];
    oe_celt_assert( n < 25 );
    oe_ec_enc_icdf( psRangeEnc, n, oe_silk_stereo_pred_joint_iCDF, 8 );
    for( n = 0; n < 2; n++ ) {
        oe_celt_assert( ix[ n ][ 0 ] < 3 );
        oe_celt_assert( ix[ n ][ 1 ] < oe_STEREO_QUANT_SUB_STEPS );
        oe_ec_enc_icdf( psRangeEnc, ix[ n ][ 0 ], oe_silk_uniform3_iCDF, 8 );
        oe_ec_enc_icdf( psRangeEnc, ix[ n ][ 1 ], oe_silk_uniform5_iCDF, 8 );
    }
}
