static int oe_opus_packet_get_nb_frames(const unsigned char packet[], oe_opus_int32 len)
{
   int count;
   if (len<1)
      return oe_OPUS_BAD_ARG;
   count = packet[0]&0x3;
   if (count==0)
      return 1;
   else if (count!=3)
      return 2;
   else if (len<2)
      return oe_OPUS_INVALID_PACKET;
   else
      return packet[1]&0x3F;
}

struct oe_OpusDREDDecoder {
   int loaded;
   int arch;
   oe_opus_uint32 magic;
};


