static oe_opus_val32 oe_silk_resampler_down2_hp(
    oe_opus_val32                  *S,
    oe_opus_val32                  *out,
    const oe_opus_val32            *in,
    int                         inLen
)
{
    int k, len2 = inLen/2;
    oe_opus_val32 in32, out32, out32_hp, Y, X;
    oe_opus_val64 hp_ener = 0;

    for( k = 0; k < len2; k++ ) {

        in32 = in[ 2 * k ];

        Y      = oe_SUB32( in32, S[ 0 ] );
        X      = oe_MULT16_32_Q15(oe_QCONST16(0.6074371f, 15), Y);
        out32  = oe_ADD32( S[ 0 ], X );
        S[ 0 ] = oe_ADD32( in32, X );
        out32_hp = out32;

        in32 = in[ 2 * k + 1 ];

        Y      = oe_SUB32( in32, S[ 1 ] );
        X      = oe_MULT16_32_Q15(oe_QCONST16(0.15063f, 15), Y);
        out32  = oe_ADD32( out32, S[ 1 ] );
        out32  = oe_ADD32( out32, X );
        S[ 1 ] = oe_ADD32( in32, X );

        Y      = oe_SUB32( -in32, S[ 2 ] );
        X      = oe_MULT16_32_Q15(oe_QCONST16(0.15063f, 15), Y);
        out32_hp  = oe_ADD32( out32_hp, S[ 2 ] );
        out32_hp  = oe_ADD32( out32_hp, X );
        S[ 2 ] = oe_ADD32( -in32, X );

        hp_ener += oe_SHR64(out32_hp*(oe_opus_val64)out32_hp, 8);

        out[ k ] = oe_HALF32(out32);
    }
    return (oe_opus_val32)hp_ener;
}
static oe_opus_val32 oe_downmix_and_resample(oe_downmix_func downmix, const void *_x, oe_opus_val32 *y, oe_opus_val32 S[3], int subframe, int offset, int c1, int c2, int C, int Fs)
{
   oe_VARDECL(oe_opus_val32, tmp);
   int j;
   oe_opus_val32 ret = 0;
   oe_SAVE_STACK;

   if (subframe==0) return 0;
   if (Fs == 48000)
   {
      subframe *= 2;
      offset *= 2;
   } else if (Fs == 16000) {
      subframe = subframe*2/3;
      offset = offset*2/3;
   }
   else if (Fs != 24000) oe_celt_assert(0);
   oe_ALLOC(tmp, subframe, oe_opus_val32);

   downmix(_x, tmp, subframe, offset, c1, c2, C);
   if ((c2==-2 && C==2) || c2>-1) {
      for (j=0;j<subframe;j++) {
         tmp[j] = oe_HALF32(tmp[j]);
      }
   }
   if (Fs == 48000)
   {
      ret = oe_silk_resampler_down2_hp(S, y, tmp, subframe);
   } else if (Fs == 24000) {
      oe_OPUS_COPY(y, tmp, subframe);
   } else if (Fs == 16000) {
      oe_VARDECL(oe_opus_val32, tmp3x);
      oe_ALLOC(tmp3x, 3*subframe, oe_opus_val32);

      for (j=0;j<subframe;j++)
      {
         tmp3x[3*j] = tmp[j];
         tmp3x[3*j+1] = tmp[j];
         tmp3x[3*j+2] = tmp[j];
      }
      oe_silk_resampler_down2_hp(S, y, tmp3x, 3*subframe);
   }
   oe_RESTORE_STACK;
   ret *= 1.f/32768/32768;
   return ret;
}
static void oe_tonality_analysis_init(oe_TonalityAnalysisState *tonal, oe_opus_int32 Fs)
{

  tonal->arch = oe_opus_select_arch();
  tonal->Fs = Fs;

  oe_tonality_analysis_reset(tonal);
}
static void oe_tonality_analysis_reset(oe_TonalityAnalysisState *tonal)
{

  char *start = (char*)&tonal->TONALITY_ANALYSIS_RESET_START;
  oe_OPUS_CLEAR(start, sizeof(oe_TonalityAnalysisState) - (start - (char*)tonal));
}
static void oe_tonality_get_info(oe_TonalityAnalysisState *tonal, oe_AnalysisInfo *info_out, int len)
{
   int pos;
   int curr_lookahead;
   float tonality_max;
   float tonality_avg;
   int tonality_count;
   int i;
   int pos0;
   float prob_avg;
   float prob_count;
   float prob_min, prob_max;
   float vad_prob;
   int mpos, vpos;
   int bandwidth_span;

   pos = tonal->read_pos;
   curr_lookahead = tonal->write_pos-tonal->read_pos;
   if (curr_lookahead<0)
      curr_lookahead += oe_DETECT_SIZE;

   tonal->read_subframe += len/(tonal->Fs/400);
   while (tonal->read_subframe>=8)
   {
      tonal->read_subframe -= 8;
      tonal->read_pos++;
   }
   if (tonal->read_pos>=oe_DETECT_SIZE)
      tonal->read_pos-=oe_DETECT_SIZE;

   if (len > tonal->Fs/50 && pos != tonal->write_pos)
   {
      pos++;
      if (pos==oe_DETECT_SIZE)
         pos=0;
   }
   if (pos == tonal->write_pos)
      pos--;
   if (pos<0)
      pos = oe_DETECT_SIZE-1;
   pos0 = pos;
   oe_OPUS_COPY(info_out, &tonal->info[pos], 1);
   if (!info_out->valid)
      return;
   tonality_max = tonality_avg = info_out->tonality;
   tonality_count = 1;

   bandwidth_span = 6;

   for (i=0;i<3;i++)
   {
      pos++;
      if (pos==oe_DETECT_SIZE)
         pos = 0;
      if (pos == tonal->write_pos)
         break;
      tonality_max = oe_MAX32(tonality_max, tonal->info[pos].tonality);
      tonality_avg += tonal->info[pos].tonality;
      tonality_count++;
      info_out->bandwidth = oe_IMAX(info_out->bandwidth, tonal->info[pos].bandwidth);
      bandwidth_span--;
   }
   pos = pos0;

   for (i=0;i<bandwidth_span;i++)
   {
      pos--;
      if (pos < 0)
         pos = oe_DETECT_SIZE-1;
      if (pos == tonal->write_pos)
         break;
      info_out->bandwidth = oe_IMAX(info_out->bandwidth, tonal->info[pos].bandwidth);
   }
   info_out->tonality = oe_MAX32(tonality_avg/tonality_count, tonality_max-.2f);

   mpos = vpos = pos0;

   if (curr_lookahead > 15)
   {
      mpos += 5;
      if (mpos>=oe_DETECT_SIZE)
         mpos -= oe_DETECT_SIZE;
      vpos += 1;
      if (vpos>=oe_DETECT_SIZE)
         vpos -= oe_DETECT_SIZE;
   }

   prob_min = 1.f;
   prob_max = 0.f;
   vad_prob = tonal->info[vpos].activity_probability;
   prob_count = oe_MAX16(.1f, vad_prob);
   prob_avg = oe_MAX16(.1f, vad_prob)*tonal->info[mpos].music_prob;
   while (1)
   {
      float pos_vad;
      mpos++;
      if (mpos==oe_DETECT_SIZE)
         mpos = 0;
      if (mpos == tonal->write_pos)
         break;
      vpos++;
      if (vpos==oe_DETECT_SIZE)
         vpos = 0;
      if (vpos == tonal->write_pos)
         break;
      pos_vad = tonal->info[vpos].activity_probability;
      prob_min = oe_MIN16((prob_avg - oe_TRANSITION_PENALTY*(vad_prob - pos_vad))/prob_count, prob_min);
      prob_max = oe_MAX16((prob_avg + oe_TRANSITION_PENALTY*(vad_prob - pos_vad))/prob_count, prob_max);
      prob_count += oe_MAX16(.1f, pos_vad);
      prob_avg += oe_MAX16(.1f, pos_vad)*tonal->info[mpos].music_prob;
   }
   info_out->music_prob = prob_avg/prob_count;
   prob_min = oe_MIN16(prob_avg/prob_count, prob_min);
   prob_max = oe_MAX16(prob_avg/prob_count, prob_max);
   prob_min = oe_MAX16(prob_min, 0.f);
   prob_max = oe_MIN16(prob_max, 1.f);

   if (curr_lookahead < 10)
   {
      float pmin, pmax;
      pmin = prob_min;
      pmax = prob_max;
      pos = pos0;

      for (i=0;i<oe_IMIN(tonal->count-1, 15);i++)
      {
         pos--;
         if (pos < 0)
            pos = oe_DETECT_SIZE-1;
         pmin = oe_MIN16(pmin, tonal->info[pos].music_prob);
         pmax = oe_MAX16(pmax, tonal->info[pos].music_prob);
      }

      pmin = oe_MAX16(0.f, pmin - .1f*vad_prob);
      pmax = oe_MIN16(1.f, pmax + .1f*vad_prob);
      prob_min += (1.f-.1f*curr_lookahead)*(pmin - prob_min);
      prob_max += (1.f-.1f*curr_lookahead)*(pmax - prob_max);
   }
   info_out->music_prob_min = prob_min;
   info_out->music_prob_max = prob_max;

}
